  2857:["Import attributes cannot be used with type-only imports or exports.","Os atributos de importação não podem ser usadas com importações ou exportações somente de tipo."],
  2858:["Import attribute values must be string literal expressions.","Os valores do atributo de importação devem ser expressões literais de cadeias de caracteres."],
  2859:["Excessive complexity comparing types '{0}' and '{1}'.","Complexidade excessiva ao comparar os tipos '{0}' e '{1}'."],
  2860:["The left-hand side of an 'instanceof' expression must be assignable to the first argument of the right-hand side's '[Symbol.hasInstance]' method.","O lado esquerdo de uma expressão 'instanceof' deve ser atribuível ao primeiro argumento do método '[Symbol.hasInstance]' do lado direito."],
  2861:["An object's '[Symbol.hasInstance]' method must return a boolean value for it to be used on the right-hand side of an 'instanceof' expression.","O método '[Symbol.hasInstance]' de um objeto deve retornar um valor booliano para que ele seja usado no lado direito de uma expressão 'instanceof'."],
