  8005:["'implements' clauses can only be used in TypeScript files.","Cláusulas 'implements' só podem ser usadas em arquivos TypeScript."],
  8006:["'{0}' declarations can only be used in TypeScript files.","As declarações '{0}' só podem ser usadas em arquivos TypeScript."],
  8008:["Type aliases can only be used in TypeScript files.","Os aliases de tipo só podem ser usados em arquivos TypeScript."],
  8009:["The '{0}' modifier can only be used in TypeScript files.","O modificador '{0}' só pode ser usado em arquivos TypeScript."],
  8010:["Type annotations can only be used in TypeScript files.","As anotações de tipo só podem ser usadas em arquivos TypeScript."],
  8011:["Type arguments can only be used in TypeScript files.","Os argumentos de tipo só podem ser usados em arquivos TypeScript."],
  8012:["Parameter modifiers can only be used in TypeScript files.","Modificadores de parâmetro só podem ser usados em arquivos TypeScript."],
  8013:["Non-null assertions can only be used in TypeScript files.","As declarações não nulas só podem ser usadas em arquivos TypeScript."],
  8016:["Type assertion expressions can only be used in TypeScript files.","As expressões de declaração de tipo só podem ser usadas em arquivos TypeScript."],
  8017:["Signature declarations can only be used in TypeScript files.","As declarações de assinatura só podem ser usadas em arquivos TypeScript."],
