  8020:["JSDoc types can only be used inside documentation comments.","Os tipos de JSDoc podem ser usados somente dentro dos comentários de documentação."],
  8021:["JSDoc '@typedef' tag should either have a type annotation or be followed by '@property' or '@member' tags.","A marca JSDoc \"@typedef\" deve ter uma anotação de tipo ou ser seguida pelas marcas \"@property\" or \"@member\"."],
  8022:["JSDoc '@{0}' is not attached to a class.","O '@{0}' do JSDoc não está anexado a uma classe."],
  8023:["JSDoc '@{0} {1}' does not match the 'extends {2}' clause.","O '@{0} {1}' do JSDoc não corresponde à cláusula 'extends {2}'."],
  8024:["JSDoc '@param' tag has name '{0}', but there is no parameter with that name.","A marcação do JSDoc \"@param\" tem o nome \"{0}\", mas não há nenhum parâmetro com esse nome."],
  8025:["Class declarations cannot have more than one '@augments' or '@extends' tag.","As declarações de classe não podem ter mais de uma marca '@augments' ou '@extends'."],
  8026:["Expected {0} type arguments; provide these with an '@extends' tag.","Espera-se {0} argumentos de tipo; forneça esses recursos com uma marca \"@extends\"."],
  8027:["Expected {0}-{1} type arguments; provide these with an '@extends' tag.","Espera-se {0}-{1} argumentos de tipo; forneça esses recursos com uma marca \"@extends\"."],
  8028:["JSDoc '...' may only appear in the last parameter of a signature.","JSDoc '...' só pode aparecer no último parâmetro de uma assinatura."],
  8029:["JSDoc '@param' tag has name '{0}', but there is no parameter with that name. It would match 'arguments' if it had an array type.","A marca '@param' do JSDoc tem o nome '{0}', mas não há nenhum parâmetro com esse nome. Ela corresponderia a 'argumentos' se tivesse um tipo de matriz."],
  8030:["The type of a function declaration must match the function's signature.","O tipo de uma declaração de função deve corresponder à assinatura da função."],
  8031:["You cannot rename a module via a global import.","Não é possível renomear um módulo por meio de uma importação global."],
  8032:["Qualified name '{0}' is not allowed without a leading '@param {object} {1}'.","O nome qualificado '{0}' não é permitido sem um '@param {object} {1}' à esquerda."],
  8033:["A JSDoc '@typedef' comment may not contain multiple '@type' tags.","Um comentário de JSDoc '@typedef' não pode conter várias marcas '@type'."],
  8034:["The tag was first specified here.","A marca foi especificada primeiro aqui."],
  8035:["You cannot rename elements that are defined in a 'node_modules' folder.","Não é possível renomear elementos definidos em uma pasta 'node_modules'."],
  8036:["You cannot rename elements that are defined in another 'node_modules' folder.","Não é possível renomear elementos definidos em outra pasta 'node_modules'."],
  8037:["Type satisfaction expressions can only be used in TypeScript files.","As expressões de satisfação de tipo só podem ser usadas em arquivos TypeScript."],
  8038:["Decorators may not appear after 'export' or 'export default' if they also appear before 'export'.","Os decoradores podem não aparecer após 'export' ou 'export default' se também aparecerem antes de 'export'."],
  8039:["A JSDoc '@template' tag may not follow a '@typedef', '@callback', or '@overload' tag","Uma marca JSDoc '@template' pode não seguir uma marca '@typedef', '@callback' ou '@overload'"],
  9005:["Declaration emit for this file requires using private name '{0}'. An explicit type annotation may unblock declaration emit.","A emissão de declaração para esse arquivo requer o uso do nome privado '{0}'. Uma anotação de tipo explícita pode desbloquear a emissão de declaração."],
  9006:["Declaration emit for this file requires using private name '{0}' from module '{1}'. An explicit type annotation may unblock declaration emit.","A emissão de declaração para esse arquivo requer o uso do nome privado '{0}' do módulo '{1}'. Uma anotação de tipo explícita pode desbloquear a emissão de declaração."],
  9007:["Function must have an explicit return type annotation with --isolatedDeclarations.","A função deve ter uma anotação de tipo de retorno explícita com --isolatedDeclarations."],
  9008:["Method must have an explicit return type annotation with --isolatedDeclarations.","O método deve ter uma anotação de tipo de retorno explícita com --isolatedDeclarations."],
  9009:["At least one accessor must have an explicit return type annotation with --isolatedDeclarations.","Pelo menos um acessório deve ter uma anotação de tipo de retorno explícita com --isolatedDeclarations."],
  9010:["Variable must have an explicit type annotation with --isolatedDeclarations.","A variável deve ter uma anotação de tipo explícita com --isolatedDeclarations."],
  9011:["Parameter must have an explicit type annotation with --isolatedDeclarations.","O parâmetro deve ter uma anotação de tipo explícito com --isolatedDeclarations."],
  9012:["Property must have an explicit type annotation with --isolatedDeclarations.","A propriedade deve ter uma anotação de tipo explícita com --isolatedDeclarations."],
  9013:["Expression type can't be inferred with --isolatedDeclarations.","O tipo de expressão não pode ser inferido com --isolatedDeclarations."],
  9014:["Computed properties must be number or string literals, variables or dotted expressions with --isolatedDeclarations.","As propriedades computadas devem ser literais de números ou cadeia de caracteres, variáveis ou expressões pontilhadas com --isolatedDeclarations."],
  9015:["Objects that contain spread assignments can't be inferred with --isolatedDeclarations.","Os objetos que contêm atribuições de espalhamento não podem ser inferidos com --isolatedDeclarations."],
  9016:["Objects that contain shorthand properties can't be inferred with --isolatedDeclarations.","Objetos que contêm propriedades abreviadas não podem ser inferidos com --isolatedDeclarations."],
  9017:["Only const arrays can be inferred with --isolatedDeclarations.","Somente matrizes const podem ser inferidas com --isolatedDeclarations."],
  9018:["Arrays with spread elements can't inferred with --isolatedDeclarations.","Matrizes com elementos espalhados não podem ser inferidas com --isolatedDeclarations."],
  9019:["Binding elements can't be exported directly with --isolatedDeclarations.","Os elementos de associação não podem ser exportados diretamente com --isolatedDeclarations."],
  9020:["Enum member initializers must be computable without references to external symbols with --isolatedDeclarations.","Os inicializadores de membros de Enumeração devem ser computáveis sem referências a símbolos externos com --isolatedDeclarations."],
  9021:["Extends clause can't contain an expression with --isolatedDeclarations.","A cláusula Extends não pode conter uma expressão com --isolatedDeclarations."],
  9022:["Inference from class expressions is not supported with --isolatedDeclarations.","Não há suporte para inferência de expressões de classe com --isolatedDeclarations."],
  9023:["Assigning properties to functions without declaring them is not supported with --isolatedDeclarations. Add an explicit declaration for the properties assigned to this function.","Não há suporte para a atribuição de propriedades a funções sem declará-las com --isolatedDeclarations. Adicione uma declaração explícita para as propriedades atribuídas a essa função."],
  9025:["Declaration emit for this parameter requires implicitly adding undefined to it's type. This is not supported with --isolatedDeclarations.","A declaração emit para esse parâmetro requer a adição implícita de undefined ao seu tipo. Não há suporte para isso com --isolatedDeclarations."],
